from pathlib import Path
import subprocess,json,hashlib
r=Path.cwd();o=r/'.work/optimize-small-20261116';rows=[]
for os,target in [('windows','x86_64-windows-gnu'),('linux','x86_64-linux-musl')]:
 for mode in ['fast','small']:
  prefix=o/(os+'-'+mode);cmd=['zig','build','-Dtarget='+target,'-Doptimize='+mode,'-Dcpu=baseline','-Dstrip=true','--prefix',str(prefix),'--summary','all']
  with (o/(os+'-'+mode+'.log')).open('wb') as f:p=subprocess.run(cmd,cwd=o/'source',stdout=f,stderr=subprocess.STDOUT)
  row={'os':os,'mode':mode,'command':cmd,'exit':p.returncode}
  if p.returncode==0:
   b=prefix/'bin'/('sigma.exe' if os=='windows' else 'sigma');row.update({'bytes':b.stat().st_size,'sha256':hashlib.sha256(b.read_bytes()).hexdigest()})
  rows.append(row);(o/'build-results.json').write_text(json.dumps(rows,indent=2)+'\n');print(os,mode,p.returncode,row.get('bytes'),flush=True)

