for os in ['windows','linux']:
 for name,definition in b.CASES.items():
  ref=None
  for mode in ['fast','small']:
   file=o/(os+'-'+mode)/'bin'/('sigma.exe' if os=='windows' else 'sigma');path=str(file);cmd=[path] if os=='windows' else ['wsl','--exec','/mnt/'+path[0].lower()+path[2:].replace('\\','/')];source='100 CONSTANT BENCH-ITERATIONS '+definition+' BENCH-RUN . DEPTH . BYE';cmd+=['-e',source];p=subprocess.run(cmd,cwd=r,capture_output=True,timeout=60);assert p.returncode==0,(os,name,mode,p.stderr);assert p.stdout.split()[-1:]==[b'0']
   if ref is None:ref=(p.stdout,p.stderr)
   else:assert (p.stdout,p.stderr)==ref,(os,name,mode)
   rows.append({'os':os,'case':name,'mode':mode,'command':cmd,'stdout':p.stdout.decode('utf-8'),'stderr':p.stderr.decode('utf-8'),'exit':p.returncode})
