from pathlib import Path
import subprocess,json,hashlib
r=Path.cwd();o=r/'.work/optimize-small-20261116';rows=[]
def local(path,os):
 s=str(path);return s.replace('\\','/') if os=='windows' else '/mnt/'+s[0].lower()+s[2:].replace('\\','/')
def run(os,mode,source):
 exe=o/(os+'-'+mode)/'bin'/('sigma.exe' if os=='windows' else 'sigma');cmd=[str(exe)] if os=='windows' else ['wsl','--exec',local(exe,os)];cmd+=['-e',source];p=subprocess.run(cmd,cwd=r,capture_output=True,timeout=60);assert p.returncode==0,(os,mode,p.stdout,p.stderr);return {'command':cmd,'exit':p.returncode,'stdout':p.stdout.decode('utf-8'),'stderr':p.stderr.decode('utf-8'),'sha256':hashlib.sha256(exe.read_bytes()).hexdigest()}
for os in ['windows','linux']:
 images={}
 for mode in ['fast','small']:
  file=o/(os+'-'+mode+'.sigma');x=run(os,mode,': SMALL-IMAGE-CHECK 10 3 - ; SEE SMALL-IMAGE-CHECK SAVE '+local(file,os)+' BYE');images[mode]=file;rows.append({'os':os,'action':'save','mode':mode,**x,'image_sha256':hashlib.sha256(file.read_bytes()).hexdigest()})
 for saved,file in images.items():
  for mode in ['fast','small']:
   x=run(os,mode,'LOAD-DICTIONARY '+local(file,os)+' SMALL-IMAGE-CHECK . DEPTH . BYE');assert x['stdout'].split()==['7','0'],x;rows.append({'os':os,'action':'load','saved_mode':saved,'mode':mode,**x})
(o/'images.json').write_text(json.dumps(rows,indent=2)+'\n');print('4 saves / 8 dictionary loads passed; images not required byte-identical')

